1	// server.js — 监制台 HTTP 层，仅监听 127.0.0.1。纯路由，业务在 lib/。
2	const path = require('path');
3	const fs = require('fs');
4	const express = require('express');
5	const { marked } = require('marked');
6	const sanitizeHtml = require('sanitize-html');
7	const config = require('./lib/core/config');
8	const store = require('./lib/core/store');
9	const gates = require('./lib/gates');
10	const pool = require('./lib/pool');
11	const roster = require('./lib/roster');
12	const life = require('./lib/lifecycle');
13	const trace = require('./lib/trace');
14	const quota = require('./lib/quota');
15	const journal = require('./lib/journal');
16	const dialogscan = require('./lib/dialogscan'); // 原生对话框哑弹扫描（施工令-012），/api/env 自检用
17	
18	// ROOT 可变（2026-08-08 首次运行向导）：没有 studio.config.json 时不再是死局——
19	// 向导建完工作区后**就地重挂**，不用重启进程。模块作用域的 let，所有闭包读到的都是新值。
20	let ROOT = config.resolveRoot();
21	let cfg = null; let initError = null;
22	if (!ROOT) initError = '未找到监制台仓库（缺 studio.config.json）。';
23	else { try { cfg = config.load(ROOT); store.ensureDirs(ROOT); } catch (e) { initError = '读配置失败：' + e.message; } }
24	
25	/* ---- 官方桩闸 STUDIO_STUB=1（施工令-039，案源 037 首启真派发 40s 事故 · 021 同族第二案）----
26	   工程队起桩台此前各自手搓空转钩（037 手搓 Module._load、038 手搓改写导出 + 越界计数器），
27	   两起事故全因**手搓漏面**：漏的从来不是自己写的那几个调用点，是没想到的那一个（server 自身
28	   的开工调用、巡检定时器、向导重挂）。根治办法不是让每个桩台作者更小心，是把闸做进服务本身。
29	
30	   硬关口径 = 直接空转 runner 模块的**派发导出**。模块对象在 require 缓存里只有一份，于是
31	   任何调用方（路由 / 巡检 setInterval / 向导就地重挂 / 今后新增的任何一处）拿到的都是哑函数，
32	   不靠调用点自觉、不随代码演进漏面。外呼面（额度真调 / 连通探测）同理停用——桩台既不派发也不计费。
33	   不置位时本块整体不执行，行为逐位不变。 */
34	const STUB = process.env.STUDIO_STUB === '1';
35	// 空转记录：哪些派发/外呼入口被调过又被拦下。随 /api/runner 下发，桩台作者一眼看清
36	// 「这台确实被调了、也确实什么都没干」——037 的事故正是没人看得见这一层才烧了 40 秒。
37	const 桩台拦截 = [];
38	if (STUB) {
39	  const r = require('./lib/runner');
40	  // 生命周期面（服务开工/停手必调）：空转即可，被调是正常的
41	  for (const k of ['start', 'stop', 'stopLoop']) r[k] = function 桩台空转() { 桩台拦截.push(k); };
42	  // 真派发面：拉起会话 / 掐会话 / 排调度循环——哑掉，且返回值取"什么都没发生"的形状
43	  r.startLoop = function 桩台空转() { 桩台拦截.push('startLoop'); };
44	  r.tick = async function 桩台空转() { 桩台拦截.push('tick'); return { skipped: true, reason: '桩台模式：派发面已硬关' }; };
45	  r.startWork = async function 桩台空转() { 桩台拦截.push('startWork'); return false; };
46	  r.killTicket = function 桩台空转() { 桩台拦截.push('killTicket'); return false; };
47	  // 外呼面：额度查询会真调 CLI/HTTP（计费+限流），连通探测会真发请求
48	  const q = require('./lib/quota');
49	  q.getRateLimits = async () => null; q.queryRateLimits = async () => null;
50	  q.getClaudeUsage = async () => null; q.queryClaudeUsage = async () => null;
51	  q.eagerRefresh = () => {};
52	  // 额度闸从严：桩台一律不放行（真派发面已哑，这里是第二道）
53	  q.checkGate = async () => ({ allowed: false, threshold: 0, reason: '桩台模式：额度查询停用，一律不放行' });
54	  const np = require('./lib/netprobe');
55	  np.httpProbe = async () => null;
56	  np.探 = async () => ({ 直连: null, 经代理: null });
57	  // 项管脑（H49）：五个入口每个都 spawn 一次 claude CLI，是全站最大的一笔计费外呼。
58	  // 「零计费」离了这一面就是空话——起草/切单/收口/答疑/代裁一律哑掉，回调按「桩台不作业」回。
59	  const brain = require('./lib/pm/brain');
60	  for (const k of ['draftTicket', 'cut', 'closeout', 'answer', 'adjudicateReferral']) {
61	    brain[k] = function 桩台空转(...args) {
62	      桩台拦截.push('brain.' + k);
63	      const cb = args[args.length - 1];
64	      if (typeof cb === 'function') cb({ ok: false, error: '桩台模式：项管脑外呼已停用' });
65	    };
66	  }
67	}
68	// /api/runner 的桩台印：桩台模式下「运行」恒 false，且带 桩台:true 让调用方一眼看出这台不是实弹台
69	const 桩台印 = (st) => (STUB ? { ...st, 桩台: true, 运行: false, 桩台拦截: [...桩台拦截] } : st);
70	
71	const app = express();
72	app.use(express.json({ limit: '2mb' }));
73	// ---- 远程访问（0.17.10）：默认只听 127.0.0.1；config.网络.远程.开 = true 时听 0.0.0.0，
74	// 一切请求须持令牌（?t= 首访换 cookie / x-studio-token 头）。实弹台有项目仓全写权，令牌是底线。
75	const REMOTE = () => (cfg && cfg.网络 && cfg.网络.远程) || {};
76	const isLocalReq = (req) => {
77	  const ip = String(req.socket.remoteAddress || '');
78	  return ip === '127.0.0.1' || ip === '::1' || ip === '::ffff:127.0.0.1';
79	};
80	const tokenOk = (req) => {
81	  const tk = REMOTE().令牌;
82	  if (!tk) return false;
83	  const got = req.query.t || req.headers['x-studio-token'] || (String(req.headers.cookie || '').match(/studio_t=([\w-]+)/) || [])[1];
84	  return got === tk;
85	};
86	app.use((req, res, next) => {
87	  const remoteOn = !!REMOTE().开;
88	  if (!isLocalReq(req)) {
89	    if (!remoteOn) return res.status(403).json({ error: '远程访问未开启' });
90	    if (!tokenOk(req)) return res.status(401).send('<meta charset="utf-8">需要访问令牌：请用带 ?t=令牌 的链接打开');
91	    if (req.query.t) res.setHeader('Set-Cookie', `studio_t=${req.query.t}; Path=/; HttpOnly; SameSite=Lax; Max-Age=2592000`);
92	    return next(); // 令牌即身份，远程写放行
93	  }
94	  // 本机请求维持原 CSRF 护栏：写请求校验本机 Host + 同源 Origin
95	  if (['GET', 'HEAD', 'OPTIONS'].includes(req.method)) return next();
96	  const LOCAL = new Set(['127.0.0.1', 'localhost', '[::1]']);
97	  const host = String(req.headers.host || '').replace(/:\d+$/, '');
98	  if (!LOCAL.has(host) && !tokenOk(req)) return res.status(403).json({ error: '拒绝：非本机写请求' });
99	  const o = req.headers.origin;
100	  if (o) { let h = null; try { h = new URL(o).hostname; } catch { h = null; }
101	    if ((!h || !LOCAL.has(h)) && !tokenOk(req)) return res.status(403).json({ error: '拒绝：跨源写请求' }); }
102	  next();
103	});
104	const ready = (res) => { if (initError) { res.status(500).json({ error: initError, 需要向导: !ROOT }); return false; } return true; };
105	
106	// ---- 首次运行向导（2026-08-08）：缺 studio.config.json 不再是死局 ----
107	// 旧样：resolveRoot 返回 null → initError → main.js showErrorBox + quit。
108	// 而**加项目的 UI 就在那个进不去的 app 里**，于是新用户只能先手写 JSON。
109	// 这两个端点**不过 ready() 闸**——它们正是用来把 app 从未就绪状态里捞出来的。
110	const setup = require('./lib/setup');
111	app.get('/api/setup/state', (req, res) => {
112	  res.json({
113	    需要向导: !ROOT || !!initError,
114	    当前工作区: ROOT || null,
115	    错误: initError || null,
116	    候选目录: setup.候选目录(),
117	  });
118	});
119	app.post('/api/setup', (req, res) => {
120	  if (!isLocalReq(req)) return res.status(403).json({ error: '建工作区只能在本机操作' });
121	  const r = setup.建工作区((req.body || {}).目录);
122	  if (!r.ok) return res.status(400).json(r);
123	  try {
124	    ROOT = r.root;                       // 就地重挂：省掉一次重启
125	    cfg = config.load(ROOT);
126	    store.ensureDirs(ROOT);
127	    docs.setZones(cfg.文档分区);
128	    initError = null;
129	    journal.append(ROOT, `首次运行向导：工作区就位于 ${ROOT}（${r.新建 ? '新建配置' : '沿用已有配置'}）`);
130	    try { runner.start(ROOT, () => cfg); } catch { /* 执行器起不来不挡向导，参数页还能手动开 */ }
131	  } catch (e) {
132	    initError = '向导建完但加载失败：' + e.message;
133	    return res.status(500).json({ ok: false, error: initError });
134	  }
135	  res.json({ ...r, 就绪: true });
136	});
137	
138	// ---- 凭据托管（2026-08-08 路 B：订阅态归 CLI，key 归 app）----
139	const creds = require('./lib/creds');
140	// 官方登录命令：可见拉起，不做无头（登录本来就是交互动作，藏进无头进程是自找麻烦——
141	// 同施工令-011「编辑器绝对可见化」的道理）。命令可在 config.执行器.登录命令 里覆盖。
142	const 登录命令 = (厂商) => {
143	  const 覆盖 = ((cfg || {}).执行器 || {}).登录命令 || {};
