app.post('/api/config/compat-pool', (req, res) => {
  if (!ready(res)) return;
  if (!isLocalReq(req)) return res.status(403).json({ error: '密钥管理只能在本机操作' });
  const { 池名, base, key, 模型 } = req.body || {};
