1	// lifecycle.js — 高层生命周期动作（D5/D6/D8/D10/D13）。每个动作 = 一次合法状态转移 + 记账。
2	// 只做控制流；产出资产由执行 agent 写进项目仓库，回执写进 回执/。
3	const fs = require('fs');
4	const path = require('path');
5	const store = require('./core/store');
6	const journal = require('./journal');
7	const inbox = require('./inbox');
8	
9	const nowIso = () => new Date().toISOString();
10	
11	// 上呈原因落库（施工令-012 / 巡礼 P2-3，通则见「优化-D」）：凡是要端到制作人面前当判断依据的
12	// 结论，一律在流转时写进 frontmatter，前端只读字段——不再靠 grep 流水回答一个本该有字段的问题。
13	// 老病灶：跨月后 journal.readLatest 只读当月文件，原始上呈行整体消失，兜底正则把「滞留告警」
14	// 这类噪声行顶上来，卷宗最重要的一栏越拖越准地误导。
15	const 记上呈原因 = (s) => String(s || '').replace(/\s+/g, ' ').trim().slice(0, 200);
16	
17	function 定稿(root, id) { // 草稿→待投（写好了，攥在手里）
18	  const t = store.find(root, id);
19	  if (!t) return { ok: false, error: '不存在' };
20	  if (t.state !== '草稿') return { ok: false, error: `只有草稿可定稿（当前 ${t.state}）` };
21	  const r = store.move(root, id, '草稿', '待投', null, nowIso());
22	  if (r.ok) journal.append(root, `定稿 ${id}（草稿→待投）`);
23	  return r;
24	}
25	
26	function 投池(root, id) { // 待投→池（人闸释放，D2）
