256	  if (!t) return { ok: false, error: '不存在' };
257	  if (t.state !== '在途') return { ok: false, error: `只有在途单可收回（当前 ${t.state}）` };
258	  const r = store.move(root, id, '在途', '池', (fm) => { delete fm.主办; delete fm.领单时间; fm.放行 = false; }, nowIso()); // 收回=收权：撤放行旗（2026-08-05 语义分家：收回待重放行，重投带放行）
259	  if (r.ok) journal.append(root, `收回 ${id}（在途→池 · 清主办 · 撤放行）`);
260	  return r;
261	}
262	
263	// 滞留检查（R3，用户修正：超时不自动撤回，改为诊断 + 告警）。
264	// 覆盖 执行中/质检/待定夺 三态：超时的单不移动，只标 滞留告警=true + 记账提醒，
265	// 由制作人在收件箱/在途面板看到后决定收回/等待/废弃。绝不自动改状态。
266	function 滞留检查(root, cfg, nowMs) {
267	  const 超时h = (cfg.闸值 || {}).滞留超时小时 ?? 4;
268	  const now = nowMs || Date.now();
269	  const 告警 = [];
270	  for (const state of ['在途', '质检', '待定夺']) {
271	    for (const t of store.list(root, state)) {
272	      if (['战役','专项'].includes(t.fm.父单类型) || ['战役','专项'].includes(t.fm.主办)) continue; // H53：父单在途=专项进行中的状态章，不适用执行滞留阈值
273	      if (t.fm.挂起) continue; // 施工令-021：挂起单停在原地是制作人的本意，报它滞留纯属噪声
274	      const 基准 = Date.parse(t.fm.领单时间 || t.fm.更新时间 || '');
275	      if (Number.isNaN(基准)) continue;
276	      const 停留h = (now - 基准) / 3600000;
277	      if (停留h > 超时h) {
278	        if (!t.fm.滞留告警) { // 只记一次，不刷屏
279	          store.update(root, t.id, (fm) => { fm.滞留告警 = true; fm.滞留时长h = Math.round(停留h); }, new Date(now).toISOString());
280	          journal.append(root, `滞留告警 ${t.id}（${state} 停留 ${Math.round(停留h)}h，超 ${超时h}h）——请人工检查，未自动撤回`);
281	          inbox.post(root, '急', '滞留告警', `${t.id} ${state} 停留 ${Math.round(停留h)}h`, { 单号: t.id });
282	        }
283	        告警.push({ id: t.id, state, 停留h: Math.round(停留h) });
284	      }
285	    }
286	  }
287	  return { 告警 };
288	}
289	
290	// 执行失败入位（D31）：纯本地目录改名，零网络依赖——执行器在 CLI 崩溃/超时/非零退出时调用。
291	// 不清主办（留作诊断线索）；执行失败不占在途口径，agent 自动空出。
292	function 执行失败(root, id, 原因) {
293	  const t = store.find(root, id);
294	  if (!t) return { ok: false, error: '不存在' };
295	  if (t.state !== '在途' && t.state !== '质检') return { ok: false, error: `当前不可标执行失败（${t.state}）` };
296	  const r = store.move(root, id, t.state, '执行失败', (fm) => {
297	    fm.失败原因 = String(原因 || '未知').slice(0, 200);
298	    fm.失败次数 = (Number(fm.失败次数) || 0) + 1;
299	    fm.失败时间 = nowIso();
300	  }, nowIso());
301	  if (r.ok) { journal.append(root, `执行失败 ${id}（${t.state}→执行失败 · ${String(原因 || '').slice(0, 60)}）——待 Claude 分诊`); inbox.post(root, '急', '执行失败', `${id} ${String(原因 || '').slice(0, 80)}`, { 单号: id }); }
302	  return r;
303	}
304	
305	// 失败分诊（D31 三出路，Claude/用户操作）：重投（清执行痕迹回池）/ 上呈（待定夺给用户）/ 废弃走通用 废弃()。
306	function 失败分诊(root, id, 决定) {
307	  const t = store.find(root, id);
308	  if (!t) return { ok: false, error: '不存在' };
309	  if (t.state !== '执行失败') return { ok: false, error: `当前不在执行失败（${t.state}）` };
310	  if (决定 === '重投') {
311	    const r = store.move(root, id, '执行失败', '池', (fm) => { delete fm.主办; delete fm.领单时间; delete fm.交付时间; fm.放行 = true; }, nowIso()); // 重投=明确指令：带放行旗过迁移（2026-08-05）
312	    if (r.ok) journal.append(root, `失败分诊 ${id}：重投（执行失败→池 · 清主办 · 带放行重新可派）`);
313	    return r;
314	  }
315	  if (决定 === '上呈') {
316	    const 因 = String(t.fm.失败原因 || '').trim();
317	    const r = store.move(root, id, '执行失败', '待定夺', (fm) => {
318	      fm.上呈原因 = 记上呈原因(`失败分诊上呈：执行失败${t.fm.失败次数 ? ` ${t.fm.失败次数} 次` : ''}${因 ? ` · ${因}` : ''}——需你拍板`);
319	    }, nowIso());
320	    if (r.ok) journal.append(root, `失败分诊 ${id}：上呈（执行失败→待定夺 · 需用户拍板）`);
321	    return r;
322	  }
323	  return { ok: false, error: `未知决定：${决定}（重投/上呈，废弃走通用废弃）` };
324	}
325	
326	// 上游改动标记（复查#8 = D36）：策划案锚号改版 → 引用它的未完成单全部标待复核。
327	// 被标记的单：池中不可领、在途不起新执行、交产出被拒——直到核对新版后解除。
328	function 标记待复核(root, 锚号, 说明) {
329	  const trace = require('./trace');
330	  const hits = trace.affectedByRef(root, 锚号);
331	  const now = nowIso();
332	  for (const h of hits) store.update(root, h.id, (fm) => { fm.待复核 = { 锚号, 说明: String(说明 || '').slice(0, 120), 标记时间: now }; }, now);
333	  journal.append(root, `上游改动标记 ${锚号}：${hits.length} 张未完成单标待复核（${hits.map((h) => h.id).join('、') || '无命中'}）`);
334	  return { ok: true, 命中: hits };
335	}
336	function 解除待复核(root, id, 确认说明) {
337	  const t = store.find(root, id);
338	  if (!t) return { ok: false, error: '不存在' };
339	  if (!t.fm.待复核) return { ok: false, error: '该单没有待复核标记' };
340	  const 锚 = t.fm.待复核.锚号;
341	  store.update(root, id, (fm) => { delete fm.待复核; fm.复核确认 = { 锚号: 锚, 时间: nowIso(), 说明: String(确认说明 || '已核对新版') }; }, nowIso());
342	  journal.append(root, `解除待复核 ${id}（${锚} 已核对新版）`);
343	  return { ok: true };
344	}
345	
346	// ---- 挂起 / 解挂（施工令-021 · 制作人裁决权补全）----
347	// 案源 TK-105/TK-S2：这类「整个方向不对、但还不到废弃」的单，制作人手上没有冻结按钮，
348	// 只能往文件里手写一句搁置令——机器读不到，派发照跑，等于没停。
349	// 三把闸的语义分家（别混）：
350	//   废弃 = 终态判决，进已归档不可逆；
351	//   收回 = 在途单退回池，活还要接着干；
352	//   挂起 = **原位冻结**——单一步不挪，只在 frontmatter 盖印，全链路筛选处一律跳过；
353	//          解挂即在原状态原位复活，接着被正常调度。所以它走 store.update 而非 store.move。
354	// 与 待复核 的分家：待复核是上游改版触发的自动标记（机器盖的），挂起是制作人手动拉的闸。
355	// 终态不可挂：完成/已归档的单本来就不参与任何调度，挂它只会平添一个没人读的字段。
356	function 挂起(root, id, 操作者, 理由, 连带自) {
357	  const t = store.find(root, id);
358	  if (!t) return { ok: false, error: '不存在' };
359	  if (store.TERMINAL.includes(t.state)) return { ok: false, error: `终态单不可挂起（当前 ${t.state}）` };
360	  if (t.fm.挂起) return { ok: false, error: '该单已挂起' };
361	  const 人 = String(操作者 || '制作人').slice(0, 40);
362	  const r = store.update(root, id, (fm) => {
363	    fm.挂起 = {
364	      操作者: 人, 时间: nowIso(), 挂起时状态: t.state, // 挂起时状态=留档快照，事实源仍是目录
365	      ...(String(理由 || '').trim() ? { 理由: String(理由).trim().slice(0, 200) } : {}),
366	      ...(连带自 ? { 连带自: String(连带自) } : {}), // 全树挂起时子单记它是被谁连带的，解挂树按此认领
367	    };
368	  });
369	  if (r.ok) journal.append(root, `挂起 ${id}（${t.state} 原位冻结 · ${人}${连带自 ? ` · 连带自 ${连带自}` : ''}${String(理由 || '').trim() ? ` · ${String(理由).trim().slice(0, 60)}` : ''}）——全链路跳过，解挂后原位复活`);
370	  return r.ok ? { ...r, state: t.state } : r;
371	}
372	
373	function 解挂(root, id, 操作者) {
374	  const t = store.find(root, id);
375	  if (!t) return { ok: false, error: '不存在' };
376	  if (!t.fm.挂起) return { ok: false, error: '该单未挂起' };
377	  const 人 = String(操作者 || '制作人').slice(0, 40);
378	  const 挂时 = t.fm.挂起.时间 || '';
379	  const r = store.update(root, id, (fm) => {
380	    fm.解挂记录 = { 操作者: 人, 时间: nowIso(), 挂起于: 挂时 }; // 冻了多久要留得下账
381	    delete fm.挂起;
382	  });
383	  if (r.ok) journal.append(root, `解挂 ${id}（${t.state} 原位复活 · ${人}）——重新进入正常调度`);
384	  return r.ok ? { ...r, state: t.state } : r;
385	}
386	
387	// 子孙盘点（全树挂起/解挂共用）：沿 父单 字段广度优先下钻，自带环路防护
388	// （手工改 frontmatter 造出 A→B→A 的父子环并非不可能，遇上就是死循环）。
389	function 子孙(root, id) {
390	  const all = [];
391	  for (const s of store.STATES) for (const x of store.list(root, s)) all.push(x);
392	  const out = []; const 见过 = new Set([String(id)]); let 层 = [String(id)];
393	  while (层.length) {
394	    const 下 = [];
395	    for (const x of all) {
396	      if (!x.fm.父单 || !层.includes(String(x.fm.父单)) || 见过.has(String(x.id))) continue;
397	      见过.add(String(x.id)); out.push(x); 下.push(String(x.id));
398	    }
399	    层 = 下;
400	  }
401	  return out;
402	}
403	
404	// 全树挂起（施工令-021 第 2 条）：专项/战役父单挂起时，制作人可选连带整棵子树。
405	// 终态子单与已挂起子单跳过并如实回报——「跳过」不是失败，制作人要看得见哪些没动、为什么。
406	function 挂起树(root, id, 操作者, 理由) {
407	  const 头 = 挂起(root, id, 操作者, 理由);
408	  if (!头.ok) return 头;
409	  const 已挂 = [id]; const 跳过 = [];
410	  for (const c of 子孙(root, id)) {
411	    if (store.TERMINAL.includes(c.state)) { 跳过.push({ id: c.id, 因: `终态（${c.state}）` }); continue; }
412	    if (c.fm.挂起) { 跳过.push({ id: c.id, 因: '已挂起' }); continue; }
413	    const r = 挂起(root, c.id, 操作者, 理由, id);
414	    if (r.ok) 已挂.push(c.id); else 跳过.push({ id: c.id, 因: r.error });
415	  }
416	  journal.append(root, `全树挂起 ${id}：连带 ${已挂.length - 1} 张子单（${已挂.slice(1).join('、') || '无'}）${跳过.length ? ` · 跳过 ${跳过.map((x) => `${x.id}(${x.因})`).join('、')}` : ''}`);
417	  return { ok: true, id, 挂起: 已挂, 跳过 };
418	}
419	
420	// 全树解挂：只放自己和**被本单连带**的子单——制作人单独挂过的子单不被顺手解开
421	// （那是另一道闸，替他解等于替他改主意）。
422	function 解挂树(root, id, 操作者) {
423	  const 头 = 解挂(root, id, 操作者);
424	  if (!头.ok) return 头;
425	  const 已解 = [id]; const 跳过 = [];
426	  for (const c of 子孙(root, id)) {
427	    if (!c.fm.挂起) continue;
428	    if (String(c.fm.挂起.连带自 || '') !== String(id)) { 跳过.push({ id: c.id, 因: '独立挂起，不代解' }); continue; }
429	    const r = 解挂(root, c.id, 操作者);
430	    if (r.ok) 已解.push(c.id); else 跳过.push({ id: c.id, 因: r.error });
431	  }
432	  journal.append(root, `全树解挂 ${id}：连带 ${已解.length - 1} 张子单（${已解.slice(1).join('、') || '无'}）${跳过.length ? ` · 保留挂起 ${跳过.map((x) => x.id).join('、')}` : ''}`);
433	  return { ok: true, id, 解挂: 已解, 跳过 };
434	}
435	
436	// 返工（D6）：归档旧单 + 建新草稿（带返工自回链）。旧单永不复活。
437	// 下游依赖自动接续：引用旧单的未终态单，依赖改指新单——否则它们会永远等一张已归档的单
438	// （地图 L0 实战教训：TK-19 返工后 TK-21 卡死，当时靠手工 撤回→改→重投 解救）。
439	function 返工(root, oldId, newId, fm, body) {
440	  const old = store.find(root, oldId);
441	  if (!old) return { ok: false, error: '旧单不存在' };
442	  if (store.isLegal(old.state, '已归档')) {
443	    store.move(root, oldId, old.state, '已归档', (f) => { f.归档原因 = '返工替代'; }, nowIso());
444	  }
445	  const nfm = { ...fm, 返工自: oldId, 创建时间: fm.创建时间 || nowIso().slice(0, 10), 更新时间: nowIso() };
446	  const r = store.create(root, newId, nfm, body);
447	  if (!r.ok) return r;
448	  const 接续 = [];
449	  for (const s of store.STATES) {
450	    if (store.TERMINAL.includes(s)) continue;
451	    for (const t of store.list(root, s)) {
452	      const deps = t.fm.依赖;
453	      if (!deps) continue;
454	      const arr = Array.isArray(deps) ? deps.map(String) : String(deps).split(/[，,\s]+/).filter(Boolean);
455	      if (!arr.includes(oldId)) continue;
456	      const next = arr.map((d) => (d === oldId ? newId : d)).join('，');
457	      store.update(root, t.id, (f) => { f.依赖 = next; });
458	      接续.push(t.id);
459	    }
460	  }
461	  journal.append(root, `返工 ${oldId} → 新单 ${newId}（归档旧 + 开新草稿${接续.length ? ` · 下游依赖接续：${接续.join('/')}` : ''}）`);
462	  return { ...r, 依赖接续: 接续 };
463	}
464	
465	// ---- 推翻重做（制作人专权·审批点）：完成/已归档单翻案 = 自动编号返工 ----
466	// D6 一脉：旧单归档不复活，新草稿带返工链与打回理由，制作人补充要求后再定稿投池。
467	function 推翻(root, id, 理由) {
468	  const t = store.find(root, id);
469	  if (!t) return { ok: false, error: '不存在' };
470	  if (!['完成', '已归档'].includes(t.state)) return { ok: false, error: `推翻只针对完成/已归档单（当前 ${t.state}，用打回/废弃）` };
471	  if (!String(理由 || '').trim()) return { ok: false, error: '推翻必须写理由（历史要能回答"为什么翻案"）' };
472	  const m = String(id).match(/^(.+)-(\d+)$/);
473	  if (!m) return { ok: false, error: '编号不含序号，无法自动派新号' };
474	  let mx = 0;
475	  for (const s of store.STATES) for (const x of store.list(root, s)) {
476	    const mm = String(x.id).match(/^(.+)-(\d+)$/);
477	    if (mm && mm[1] === m[1]) mx = Math.max(mx, Number(mm[2]));
478	  }
479	  const newId = `${m[1]}-${mx + 1}`;
480	  const fm = {
481	    id: newId, title: `${t.fm.title}（推翻重做）`, 职能: t.fm.职能, 产出物类型: t.fm.产出物类型,
482	    优先级: t.fm.优先级 || 'P1', 规模: t.fm.规模 || '单兵', QA: t.fm.QA || '开',
483	    验收方式: t.fm.验收方式 || '保留', 预计时间: t.fm.预计时间 || '', 预计token: '',
484	    项目: t.fm.项目, ...(t.fm.阶段 ? { 阶段: t.fm.阶段 } : {}), ...(t.fm.父单 ? { 父单: t.fm.父单 } : {}),
485	    ...(t.fm.依赖 ? { 依赖: t.fm.依赖 } : {}),
486	  };
487	  const body = `## 推翻理由（制作人）\n${String(理由).trim()}\n\n${t.body || ''}`;
488	  // 完成→已归档 不在常规状态机里（完成=成功终态）——翻案是制作人特权，此处强制归档
489	  if (t.state === '完成') store.move(root, id, '完成', '已归档', (f) => { f.归档原因 = '推翻替代（制作人翻案）'; }, nowIso());
490	  const r = 返工(root, id, newId, fm, body);
491	  if (r.ok) journal.append(root, `推翻重做 ${id} → ${newId}（制作人翻案：${String(理由).trim().slice(0, 60)}）`);
492	  return r.ok ? { ...r, 新单: newId } : r;
493	}
494	
495	// ---- 隐藏归档（制作人专权）：已归档单从一切默认视图湮灭，纸面仍在可考 ----
496	function 隐藏(root, id, 值) {
497	  const t = store.find(root, id);
498	  if (!t) return { ok: false, error: '不存在' };
499	  if (t.state !== '已归档') return { ok: false, error: `只有已归档单可隐藏（当前 ${t.state}）` };
500	  const on = 值 !== false;
501	  const r = store.update(root, id, (fm) => { if (on) fm.隐藏 = true; else delete fm.隐藏; });
502	  if (r.ok) journal.append(root, `隐藏归档 ${id} → ${on ? '隐藏（默认视图不再渲染）' : '取消隐藏'}`);
503	  return r;
504	}
505	
506	module.exports = {
507	  定稿, 投池, 交产出, QA裁定, 定夺, 验收, 撤回, 废弃, 收回, 返修, 滞留检查, 返工, 执行失败, 失败分诊,
508	  引擎门禁命中, 引擎门禁特征, 引擎门禁默认特征, 候引擎实证, 实证放行, // 施工令-032② H97
509	  标记待复核, 解除待复核, 推翻, 隐藏,
510	  挂起, 解挂, 挂起树, 解挂树, 子孙,
511	};
512

