{
  "name": "studio-console",
  "version": "0.26.4",
  "private": true,
  "description": "监制台：AI 工作室制作人驾驶舱。工单 .md 是唯一事实源，目录即状态机。",
  "main": "main.js",
  "scripts": {
    "start": "node server.js",
    "desktop": "electron .",
    "dist": "electron-builder --win portable",
    "test": "node test/store.test.js && node test/pool.test.js && node test/lifecycle.test.js && node test/gates.test.js && node test/trace.test.js && node test/recommend.test.js && node test/roster.test.js && node test/runner.test.js && node test/stylelib.test.js && node test/config.test.js && node test/ledger.test.js && node test/stages.test.js && node test/report.test.js && node test/engines.test.js && node test/artifacts.test.js && node test/relay.test.js && node test/assembler.test.js && node test/dispatch.test.js && node test/dispatch-tick.test.js && node test/ideas.test.js && node test/wake.test.js && node test/wiki.test.js && node test/docs.test.js && node test/codoc.test.js && node test/patrol.test.js && node test/progress.test.js && node test/preflight.test.js && node test/brain.test.js && node test/chain.test.js && node test/precheck.test.js && node test/journal.test.js && node test/crew.test.js && node test/concurrency.test.js && node test/escalation.test.js && node test/dialogscan.test.js && node test/netprobe.test.js && node test/creds.test.js && node test/setup.test.js && node test/stub.test.js && node test/budget-接线.test.js"
  },
  "dependencies": {
    "express": "^4.19.0",
    "gray-matter": "^4.0.3",
    "marked": "^12.0.0",
    "sanitize-html": "^2.13.0"
  },
  "devDependencies": {
    "electron": "^30.5.1",
    "electron-builder": "^24.13.3"
  },
  "build": {
    "appId": "local.studio.console",
    "productName": "监制台",
    "directories": {
      "output": "D:/studio-build/dist"
    },
    "files": [
      "main.js",
      "server.js",
      "lib/**",
      "public/**",
      "node_modules/**",
      "preload.js"
    ],
    "win": {
      "target": "portable",
      "signAndEditExecutable": false,
      "icon": "build-assets/icon.ico"
    }
  },
  "author": "suxing412"
}
=== config ===
// core/config.js — studio.config.json 的唯一加载点。
// 仓库根 = 监制台仓库（含状态目录 + studio.config.json + _app）。
const fs = require('fs');
const path = require('path');

function resolveRoot(from) {
  if (process.env.STUDIO_ROOT) return path.resolve(process.env.STUDIO_ROOT);
  let dir = from || process.env.PORTABLE_EXECUTABLE_DIR || path.resolve(__dirname, '..', '..', '..');
  for (let i = 0; i < 6; i++) {
    if (fs.existsSync(path.join(dir, 'studio.config.json'))) return dir;
    const up = path.dirname(dir);
    if (up === dir) break;
    dir = up;
  }
  return null;
}

function load(root) {
  // 容忍 UTF-8 BOM（﻿）：PowerShell 5.1 的 -Encoding UTF8 与记事本都会写 BOM，
  // 直接 JSON.parse 会炸——0.8.1 套件 E2E 实测：部署脚本改完配置，exe 启动即崩。
  const raw = fs.readFileSync(path.join(root, 'studio.config.json'), 'utf8');
  const cfg = JSON.parse(raw.charCodeAt(0) === 0xFEFF ? raw.slice(1) : raw);
  // 编制去岗位化迁移（H85 补章）：旧 config.agents（程序-A/程序-B 岗位册）→ 新 config.编制
  // （每职能一行 + 池序）。读盘即迁移、迁移即落盘——生产配置的实际改形由运行时完成，不手改。
  // 幂等：已是新形态则 migrate 返回 false，不产生多余写盘。写失败不拦启动（内存态已是新形态）。
  try { if (require('../roster').migrate(cfg)) save(root, cfg); } catch { /* 只读盘/权限不足：本次内存迁移照常生效 */ }
  return cfg;
}

// 配置落盘的唯一实现（server 的 saveCfg 也走这里）：JSON 2 空格 + 末尾换行，无 BOM。
function save(root, cfg) {
  fs.writeFileSync(path.join(root, 'studio.config.json'), JSON.stringify(cfg, null, 2) + '\n', 'utf8');
}

module.exports = { load, save, resolveRoot };

