// ---- 排程台账（施工令-040 · Q1 后端半）----
// 案源 2026-08-11 点名巡礼：「监制台看不到后续的队列工作」。计划粒 = 尚未成单的批次计划项，
// 业务全在 lib/pm/schedule（事件折叠/状态机/CAS 都在那儿可单测），此处**只做路由**：
// 取参 → 调 → 按 ok 决定状态码。三条写路由一律显式带 预期版本（CAS 是 API 层的硬要求，
// 不是"底层顺手做了"——版本冲突回 409 并把现态一起下发，前端照着重试即可）。
// 消费接线（流程页/总览/晨晚报）在施工令-041，本令不动前端。
const schedule = require('./lib/pm/schedule');
app.get('/api/schedule', (req, res) => {
  if (!ready(res)) return;
  const 粒 = schedule.现态(ROOT); // 已按 批/序 排好：排序口径在 lib 里唯一，消费端不许各排各的
  const 计数 = {};
  for (const s of schedule.状态全集) 计数[s] = 粒.filter((g) => g.状态 === s).length;
  res.json({ 粒, 计数, 状态全集: schedule.状态全集, 转移表: schedule.转移表 });
});
app.post('/api/schedule/登记', (req, res) => {
  if (!ready(res)) return;
  const b = req.body || {};
  const r = schedule.登记(ROOT, b.粒 || b.批次 || [], b.操作者);
  if (!r.ok) return res.status(400).json(r);
  记事件('排程登记', { 新增: r.新增.length, 跳过: r.跳过.length, 操作者: String(b.操作者 || '') });
  res.json(r);
});
app.post('/api/schedule/转移', (req, res) => {
  if (!ready(res)) return;
  const b = req.body || {};
  const 人 = String(b.操作者 || '').trim();
  if (!schedule.操作域.转移.includes(人)) return res.status(403).json({ error: `转移权在 ${schedule.操作域.转移.join('/')}（收到「${人 || '空'}」）` });
  const r = schedule.转移(ROOT, { 粒ID: b.粒ID, 目标: b.目标, 预期版本: b.预期版本, 操作者: 人, 单号: b.单号, 说明: b.说明 });
  if (!r.ok) return res.status(r.冲突 ? 409 : 400).json(r); // 409 = 拿旧版本写，前端据此静默重试；400 = 语义就不对，重试也没用
  记事件('排程转移', { 粒ID: b.粒ID, 目标: b.目标, 单号: r.粒.单号 || '' });
  res.json(r);
});
app.post('/api/schedule/调整', (req, res) => {
  if (!ready(res)) return;
  const b = req.body || {};
  const r = schedule.调整(ROOT, { 粒ID: b.粒ID, 预期版本: b.预期版本, 序: b.序, 依赖: b.依赖, 池衡建议: b.池衡建议, 操作者: b.操作者, 说明: b.说明 });
  if (!r.ok) return res.status(r.冲突 ? 409 : 400).json(r);
  记事件('排程调整', { 粒ID: b.粒ID, 操作者: String(b.操作者 || '') });
  res.json(r);
});

