// GET = 聚合快照（审检+零输出在 config、池并发在台账，一处看得全）；
// POST = {审检?,零输出分钟?,池?:{codex,claude,deepseek},理由}，整批校验通过才落，记账口径同编制调整。
const concurrency = require('./lib/concurrency');
