  实证放行: (b) => life.实证放行(ROOT, b.id, b.操作者, b.说明), // 施工令-032② H97：门禁单核查过后候检，总监确认引擎证据入回执 → 转完成
  推翻: (b) => life.推翻(ROOT, b.id, b.理由), // 制作人翻案：完成/已归档 → 自动编号返工草稿
  隐藏: (b) => life.隐藏(ROOT, b.id, b.值), // 隐藏归档：默认视图湮灭，纸面可考
