  const list = cfg.模型.可选[pool] = cfg.模型.可选[pool] || [];
  if (!list.includes(v)) list.push(v);
  saveCfg();
  journal.append(ROOT, `可选模型增补：${pool} + ${v}`);
  res.json({ ok: true, 可选: cfg.模型.可选 });
});

