  let out = '';
  child.stdout.on('data', (d) => { out += d; if (out.length > 900000) out = out.slice(-450000); });
  const timer = setTimeout(() => { try { spawn('taskkill', ['/pid', String(child.pid), '/T', '/F'], { windowsHide: true }); } catch { /**/ } }, 10 * 60000);
