// ---- ② 巡礼报告 §六 Q 队列 ----
function 解析巡礼(md, { 文件名 = '巡礼报告.md' } = {}) {
  const sec = 章节(md, /^六[、.．\s)]|^6[、.．\s)].*队列|后续队列/);
  if (sec == null) return { 粒: [], 报: ['未找到 §六 队列章节'] };
  const 粒 = [];
  for (const raw of sec.split(/\r?\n/)) {
    const line = raw.trim();
