// 跑全套：从 package.json 的 test 脚本里抽出所有 test/*.js 逐个跑，汇总结果
const { execFileSync } = require('child_process');
const fs = require('fs');
const path = require('path');
const dir = 'D:/GitHub/Ticketflow/apps/studio';
const script = JSON.parse(fs.readFileSync(path.join(dir, 'package.json'), 'utf8')).scripts.test;
const files = [...script.matchAll(/node (test\/[^\s&]+)/g)].map((m) => m[1]);
let fail = 0; const 慢 = [];
for (const f of files) {
  const t0 = Date.now();
  try {
    const out = execFileSync(process.execPath, [f], { cwd: dir, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], timeout: 300000 });
    const last = out.trim().split(/\r?\n/).pop();
    console.log(`PASS  ${f.padEnd(34)} ${last}`);
  } catch (e) {
    fail++;
    console.log(`FAIL  ${f}`);
    console.log((e.stdout || '') + (e.stderr || ''));
  }
  慢.push([f, Date.now() - t0]);
}
console.log(`\n共 ${files.length} 个测试文件，失败 ${fail} 个`);
process.exit(fail ? 1 : 0);

