const server = require(dir + '/server');
const B = 'http://127.0.0.1:4297';
const 日 = (标题, s, j) => console.log(`\n[${s}] ${标题}\n` + JSON.stringify(j, null, 1).slice(0, 700));
const get = async (u) => { const r = await fetch(B + u); return [r.status, await r.json()]; };
const post = async (u, body) => {
  const r = await fetch(B + u, { method: 'POST', headers: { 'content-type': 'application/json', host: '127.0.0.1:4297' }, body: JSON.stringify(body) });
  return [r.status, await r.json()];
};

