    日('POST /api/schedule/转移（起草中→完成，非法 → 400 并留痕）', s, j);

    [s, j] = await post('/api/schedule/转移', { 操作者: '总监', 粒ID, 目标: '已成单', 预期版本: 3 });
    日('POST /api/schedule/转移（→已成单）', s, j);
    [s, j] = await post('/api/schedule/转移', { 操作者: '总监', 粒ID, 目标: '撤销', 预期版本: 4 });
