    try { runner.start(ROOT, () => cfg); } catch { /* 执行器起不来不挡向导，参数页还能手动开 */ }
  } catch (e) {
    initError = '向导建完但加载失败：' + e.message;
    return res.status(500).json({ ok: false, error: initError });
