});
app.post('/api/creds/remove', (req, res) => {
  if (!ready(res)) return;
  if (!isLocalReq(req)) return res.status(403).json({ error: '密钥管理只能在本机操作' });
  const r = creds.remove(ROOT, String((req.body || {}).池 || ''));
