25	// 子进程里求值 server.js 并回报现场。只 require 不 start——require 本身不监听端口、不派发。
26	// 表达式可返回 Promise，统一 await 后回传。
27	function 探(env, 表达式) {
28	  const code = `
29	    require(${JSON.stringify(SERVER)});
30	    const r = require(${模块('runner')});
31	    const q = require(${模块('quota')});
32	    const np = require(${模块('netprobe')});
