35	      .then((v) => { process.stdout.write('@@' + JSON.stringify(v) + '@@'); process.exit(0); })
36	      .catch((e) => { process.stdout.write('@@' + JSON.stringify({ __错: String(e && e.message) }) + '@@'); process.exit(0); });
37	  `;
38	  const out = execFileSync(process.execPath, ['-e', code], {
39	    env: { ...process.env, ...env }, encoding: 'utf8', timeout: 60000,
40	  });
41	  const v = JSON.parse(out.split('@@')[1]);
42	  if (v && v.__错) throw new Error('子进程求值失败：' + v.__错);
43	  return v;
44	}
45	// 桩台工作区：配置齐全（否则 initError 挡住 /api/runner），零工单（第二道保险）
46	function 桩台仓() {
