57	/* ===================== 一、桩闸置位：派发面与外呼面全哑 ===================== */
58	
59	t('①置位：runner 派发面整族被换成空转（start/stop/stopLoop/startLoop/tick/startWork/killTicket）', () => {
60	  const 名 = 探({ STUDIO_STUB: '1', STUDIO_ROOT: 桩台仓() }, `${JSON.stringify(派发面)}.map((k) => r[k].name)`);
61	  assert.deepEqual(名, 派发面.map(() => '桩台空转'));
62	});
