64	t('①置位：tick / startWork 调了也不派发——返回「什么都没发生」，running 表始终空', () => {
65	  const v = 探({ STUDIO_STUB: '1', STUDIO_ROOT: 桩台仓() },
66	    `(async () => ({ tick: await r.tick('x', {}), 起工: await r.startWork('x', {}, {}, 'a', '执行'), 在跑: r.running.size }))()`);
67	  assert.equal(v.tick.skipped, true);
68	  assert.match(v.tick.reason, /桩台模式：派发面已硬关/);
