73	t('①置位：外呼面停用——额度查询恒空、连通探测恒空、项管脑五入口全哑', () => {
74	  const v = 探({ STUDIO_STUB: '1', STUDIO_ROOT: 桩台仓() }, `(async () => ({
75	    额度: await q.getRateLimits({}), 用量: await q.getClaudeUsage({}), 原始: await q.queryRateLimits(),
76	    闸: await q.checkGate({}),
77	    探针: await np.探(''), 原始探针: await np.httpProbe('http://x', null),
