80	  assert.equal(v.额度, null); assert.equal(v.用量, null); assert.equal(v.原始, null);
81	  assert.equal(v.闸.allowed, false, '桩台额度闸竟放行');
82	  assert.match(v.闸.reason, /桩台模式/);
83	  assert.deepEqual(v.探针, { 直连: null, 经代理: null });
84	  assert.equal(v.原始探针, null);
85	  assert.deepEqual(v.脑, 脑面.map(() => '桩台空转'), '项管脑外呼未停用（每个入口都 spawn 一次 claude CLI）');
86	});
