const codoc = require('./lib/codoc');
const codocArg = (req, k, alias) => String((req.query && (req.query[k] ?? req.query[alias]))
  ?? (req.body && (req.body[k] ?? req.body[alias])) ?? '');
app.get('/api/codoc', (req, res) => {
