  const proj = String(req.query.项目 || '') || (cfg.项目 && cfg.项目.默认) || '';
  res.json({ 阶段: stages.stagesFor(cfg, proj), 标准: stages.parseStandards(ROOT) });
});

// 单个 agent 执行池切换已并入 /api/pm/roster（H85）。在途安全性不变：领单时池名已盖章进工单
